import{_ as a,c as i,o as t,ax as s}from"./chunks/framework.DHqKNX4U.js";const u=JSON.parse('{"title":"Upgrading Your Instance","description":"","frontmatter":{},"headers":[],"relativePath":"user-guides/upgrade-and-migration/upgrade.md","filePath":"user-guides/upgrade-and-migration/upgrade.md"}'),n={name:"user-guides/upgrade-and-migration/upgrade.md"};function r(o,e,d,l,h,c){return t(),i("div",null,e[0]||(e[0]=[s('<h1 id="upgrading-your-instance" tabindex="-1">Upgrading Your Instance <a class="header-anchor" href="#upgrading-your-instance" aria-label="Permalink to &quot;Upgrading Your Instance&quot;">​</a></h1><p>This guide provides instructions for upgrading your Open Archiver instance to the latest version.</p><h2 id="checking-for-new-versions" tabindex="-1">Checking for New Versions <a class="header-anchor" href="#checking-for-new-versions" aria-label="Permalink to &quot;Checking for New Versions&quot;">​</a></h2><p>Open Archiver automatically checks for new versions and will display a notification in the footer of the web interface when an update is available. You can find a list of all releases and their release notes on the <a href="https://github.com/LogicLabs-OU/OpenArchiver/releases" target="_blank" rel="noreferrer">GitHub Releases</a> page.</p><h2 id="upgrading-your-instance-1" tabindex="-1">Upgrading Your Instance <a class="header-anchor" href="#upgrading-your-instance-1" aria-label="Permalink to &quot;Upgrading Your Instance&quot;">​</a></h2><p>To upgrade your Open Archiver instance, follow these steps:</p><ol><li><p><strong>Pull the latest changes from the repository</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre></div></li><li><p><strong>Pull the latest Docker images</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre></div></li><li><p><strong>Restart the services with the new images</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ol><p>This will restart your Open Archiver instance with the latest version of the application.</p><h2 id="migrating-data" tabindex="-1">Migrating Data <a class="header-anchor" href="#migrating-data" aria-label="Permalink to &quot;Migrating Data&quot;">​</a></h2><p>When you upgrade to a new version, database migrations are applied automatically when the application starts up. This ensures that your database schema is always up-to-date with the latest version of the application.</p><p>No manual intervention is required for database migrations.</p><p>There is one exception, and it applies only when upgrading from v0.5.1. If the application fails to start with <code>index row requires N bytes, maximum size is 8191</code> in the migration output, see <a href="./../troubleshooting/long-message-id.html">Long Message-ID Headers</a>.</p><h2 id="the-admin-email-and-admin-password-variables-are-no-longer-used" tabindex="-1">The <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code> variables are no longer used <a class="header-anchor" href="#the-admin-email-and-admin-password-variables-are-no-longer-used" aria-label="Permalink to &quot;The `ADMIN_EMAIL` and `ADMIN_PASSWORD` variables are no longer used&quot;">​</a></h2><p>Very early versions of Open Archiver configured the administrator account through the <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code> environment variables. A compatibility shim kept honouring them and created the account automatically on first start. That shim has been removed.</p><p>The first administrator is now created only on the <code>/setup</code> page, which appears automatically the first time you open an instance that has no accounts yet. If your <code>.env</code> still defines <code>ADMIN_EMAIL</code> or <code>ADMIN_PASSWORD</code>, they are ignored and can be deleted.</p><p>Instances that already completed the upgrade are unaffected, because the administrator account is stored in the database. Only an instance that has never had a user created — for example a reinstall against an empty database — will show the setup page again.</p><h2 id="duplicate-emails-and-stalled-sources-in-v0-5-4" tabindex="-1">Duplicate emails and stalled sources in v0.5.4 <a class="header-anchor" href="#duplicate-emails-and-stalled-sources-in-v0-5-4" aria-label="Permalink to &quot;Duplicate emails and stalled sources in v0.5.4&quot;">​</a></h2><p>Before v0.5.4, two sync cycles could run over the same mailbox at the same time. Both checked for an existing copy of a message, both found none, and both archived it. Ingestion sources covering the same mailbox therefore ended up reporting different email counts while every one of them reported a successful sync.</p><p>v0.5.4 stops the cycles from overlapping, so no new duplicates are created. <strong>Copies already in your archive are left exactly as they are.</strong> The upgrade does not delete any email, and no migration touches your data.</p><p>If you want to find the copies already in your archive, an email archived twice carries the same <code>Message-ID</code> and the same content as its copy, and the two were archived within a second of each other. Removing them is not offered in this version.</p><p>The same release also frees ingestion sources that had silently stopped syncing. A source interrupted mid-cycle could be left showing a status of <code>syncing</code> that never finished, and because only <code>active</code> and <code>error</code> sources are scheduled, it was never picked up again — it simply stopped archiving new mail while continuing to look busy. Such a source is now detected and rescheduled automatically within one sync cycle after the upgrade, and archives whatever it missed in the meantime. Mail deleted from the mail server while a source was stalled cannot be recovered.</p><h2 id="upgrading-meilisearch" tabindex="-1">Upgrading Meilisearch <a class="header-anchor" href="#upgrading-meilisearch" aria-label="Permalink to &quot;Upgrading Meilisearch&quot;">​</a></h2><p>When an Open Archiver update includes a major version change for Meilisearch, you will need to manually migrate your search data. This process is not covered by the standard upgrade commands.</p><p>For detailed instructions, please see the <a href="./meilisearch-upgrade.html">Meilisearch Upgrade Guide</a>.</p>',24)]))}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
